import { assertEquals, assertNotEquals, assertThrows } from '@std/assert';
import { decodeBase64, encodeBase64 } from '@std/encoding/base64';
import { rgbaToThumbHash } from '#melofon/thumbhash.ts';
import { dominantColor } from '#melofon/dominant-color.ts';
import reference from './fixtures/thumbhash-reference.json' with {
  type: 'json',
};

// Fixed vectors from the unmodified official JS, never generated by the port.
// Fixture provenance and regeneration details: fixtures/thumbhash-reference.md.
for (const vector of reference.vectors) {
  Deno.test(`ThumbHash reference: ${vector.name}`, () => {
    const rgba = decodeBase64(vector.rgba);
    const original = rgba.slice();
    const hash = rgbaToThumbHash(vector.w, vector.h, rgba);
    assertEquals(hash, decodeBase64(vector.hash));
    assertEquals(encodeBase64(hash), vector.hash);
    assertEquals(
      rgba,
      original,
      'encoding must not mutate shared thumbnail pixels',
    );
  });
}

function pixels(colors: number[][]): Uint8Array {
  return new Uint8Array(colors.flat());
}

Deno.test('ThumbHash: transparent RGB is irrelevant; partial alpha is straight', () => {
  const hiddenRed = pixels([[255, 0, 0, 0], [10, 200, 30, 255]]);
  const hiddenBlue = pixels([[0, 0, 255, 0], [10, 200, 30, 255]]);
  assertEquals(
    rgbaToThumbHash(2, 1, hiddenRed),
    rgbaToThumbHash(2, 1, hiddenBlue),
  );
  const straight = pixels([[200, 100, 50, 128], [0, 255, 0, 255]]);
  const premultiplied = pixels([[100, 50, 25, 128], [0, 255, 0, 255]]);
  assertNotEquals(
    rgbaToThumbHash(2, 1, straight),
    rgbaToThumbHash(2, 1, premultiplied),
  );
});

Deno.test('ThumbHash: exact RGBA shape and bounded positive integer dimensions', () => {
  for (
    const [w, h] of [
      [0, 1],
      [1, 0],
      [-1, 1],
      [1.5, 1],
      [1, 1.5],
      [101, 1],
      [1, 101],
      [NaN, 1],
      [1, Infinity],
    ]
  ) {
    assertThrows(() => rgbaToThumbHash(w, h, new Uint8Array(4)), RangeError);
  }
  for (const length of [0, 3, 5, 8]) {
    assertThrows(
      () => rgbaToThumbHash(1, 1, new Uint8Array(length)),
      RangeError,
    );
  }
});

Deno.test('placeholder encoders: honor subarray boundaries and return independent results', () => {
  const backing = pixels([[0, 255, 0, 255], [51, 102, 153, 255], [
    255,
    0,
    0,
    255,
  ]]);
  const view = backing.subarray(4, 8);
  const before = backing.slice();
  const first = rgbaToThumbHash(1, 1, view);
  const expected = first.slice();
  first.fill(0);
  assertEquals(rgbaToThumbHash(1, 1, view), expected);
  assertEquals(dominantColor(view), '#336699');
  assertEquals(backing, before);
});

Deno.test('dominant color: empty, solid and exact within-bin means', () => {
  assertEquals(dominantColor(new Uint8Array()), '');
  assertEquals(dominantColor(pixels([[51, 102, 153, 255]])), '#336699');
  assertEquals(
    dominantColor(pixels([[16, 32, 48, 255], [31, 47, 63, 255]])),
    '#182838',
  );
  assertThrows(() => dominantColor(new Uint8Array(3)), RangeError);
});

Deno.test('dominant color: prevalent field beats average and salient patches', () => {
  const white = Array.from({ length: 96 }, () => [250, 250, 250, 255]);
  const red = Array.from({ length: 4 }, () => [255, 0, 0, 255]);
  assertEquals(dominantColor(pixels([...white, ...red])), '#fafafa');
  assertEquals(
    dominantColor(pixels([...white.map(() => [5, 5, 5, 255]), ...red])),
    '#050505',
  );
  // A 60/40 red/blue image is red, not the average purple (#990066).
  assertEquals(
    dominantColor(pixels([
      ...Array.from({ length: 6 }, () => [255, 0, 0, 255]),
      ...Array.from({ length: 4 }, () => [0, 0, 255, 255]),
    ])),
    '#ff0000',
  );
});

Deno.test('dominant color: merges gradient bins before choosing the heaviest cluster', () => {
  const rgba = new Uint8Array(40 * 40 * 4);
  for (let y = 0; y < 40; y++) {
    for (let x = 0; x < 40; x++) {
      rgba.set(
        x < 30 ? [16, 32, 160 + x, 255] : [255, 204, 0, 255],
        (y * 40 + x) * 4,
      );
    }
  }
  // 75% blue spanning three bins; its exact channel mean rounds 174.5 to 175.
  assertEquals(dominantColor(rgba), '#1020af');
});

Deno.test('dominant color: count ties use ascending bin index, independent of pixel order', () => {
  const redBlue = pixels([[255, 0, 0, 255], [0, 0, 255, 255]]);
  const blueRed = pixels([[0, 0, 255, 255], [255, 0, 0, 255]]);
  assertEquals(dominantColor(redBlue), '#0000ff');
  assertEquals(dominantColor(blueRed), '#0000ff');
});

Deno.test('dominant color: alpha is ignored, including fully transparent hidden RGB', () => {
  const rgba = pixels([[255, 0, 0, 0], [255, 0, 0, 128], [0, 0, 255, 255]]);
  assertEquals(dominantColor(rgba), '#ff0000');
  assertEquals(dominantColor(pixels([[51, 102, 153, 0]])), '#336699');
  for (let i = 3; i < rgba.length; i += 4) rgba[i] = 255;
  assertEquals(dominantColor(rgba), '#ff0000');
});
